<?php namespace App\Http\Controllers; use App\Models\{Product,Wishlist}; class WishlistController extends Controller { public function toggle(Product $product){$w=Wishlist::where('user_id',auth()->id())->where('product_id',$product->id)->first();$w?$w->delete():Wishlist::create(['user_id'=>auth()->id(),'product_id'=>$product->id]);return back()->with('success',$w?'Removed from wishlist.':'Added to wishlist.');}}
